    let v = theme[key];
    if (d && d[key]) v = dlgMerge(v, d[key]);
    if (c[charKey || key]) v = dlgMerge(v, c[charKey || key]);
    if (n[nodeKey || key]) v = dlgMerge(v, n[nodeKey || key]);
