    opts = opts || {};
    cfg = normalizeHomeScreen(cfg);
    const preview = !!opts.preview;
    let playing = !preview || !!opts.play;
    let settings = HomeSettings.get();
    const timers = [], layers = {}, media = [], offs = [];
    let destroyed = false, panel = null, t0 = Date.now();
    let par = { x: 0, y: 0 };

    // polices personnalis\xE9es (FontFace : aucune injection de CSS)
