        b.addEventListener("pointerenter", function (e) { if (hoverable(e) && !T.disabled) { setBtnState(T, "hover"); emit("onHover", L.id); hoverFx(T); } });
        b.addEventListener("pointerleave", function () { setBtnState(T, "normal"); });
        b.addEventListener("pointerdown", function () { if (!T.disabled) { setBtnState(T, "pressed"); emit("onPress", L.id); } });
        b.addEventListener("pointerup", function () { setBtnState(T, "normal"); });
        b.addEventListener("pointercancel", function () { setBtnState(T, "normal"); });
        b.addEventListener("focus", function () { if (!T.disabled) { setBtnState(T, "hover"); emit("onFocus", L.id); } });
        b.addEventListener("blur", function () { setBtnState(T, "normal"); });
